// Texto de un código en el idioma pedido (0 = español, 1 = inglés, 2 = alemán), o nullptr si no se conoce
inline const char* averiaTexto(uint8_t code, int lang) {
  for (const Averia& a : AVERIAS) if (a.code == code) return lang == 1 ? a.en : lang == 2 ? a.de : a.es;
  return nullptr;
}
